values.value:
{
 "type": "object",
 "properties": {
  "patch": {
   "type": "array",
   "items": {
    "type": "object",
    "properties": {
     "op": {
      "type": "string",
      "enum": [
       "add",
       "update",
       "remove",
       "setExclusion",
       "setFilter"
      ]
     },
     "id": {
      "type": "string",
      "description": "Chip id, for update and remove."
     },
     "item": {
      "type": "object",
      "properties": {
       "kind": {
        "type": "string",
        "enum": [
         "title",
         "skill",
         "certification",
         "location",
         "keyword",
         "language",
         "shift",
         "availability"
        ]
       },
       "label": {
        "type": "string",
        "description": "Chip text shown to the user, max 120 characters. For a location: 'Town + N mi'."
       },
       "value": {
        "type": "string",
        "description": "Term sent to the search. Town or postcode for a location."
       },
       "weight": {
        "type": "string",
        "enum": [
         "required",
         "strongly_preferred",
         "preferred",
         "excluded"
        ]
       },
       "radius": {
        "type": "number",
        "description": "Location only."
       },
       "unit": {
        "type": "string",
        "enum": [
         "mi",
         "km"
        ],
        "description": "Location only."
       },
       "withinDays": {
        "type": "integer",
        "description": "Availability only: available within this many days of Today."
       }
      },
      "required": [
       "kind",
       "label",
       "value",
       "weight"
      ]
     },
     "set": {
      "type": "object",
      "description": "Fields to change on the chip for update: label, value, weight, radius, unit, withinDays.",
      "properties": {
       "label": {
        "type": "string"
       },
       "value": {
        "type": "string"
       },
       "weight": {
        "type": "string",
        "enum": [
         "required",
         "strongly_preferred",
         "preferred",
         "excluded"
        ]
       },
       "radius": {
        "type": "number"
       },
       "unit": {
        "type": "string",
        "enum": [
         "mi",
         "km"
        ]
       },
       "withinDays": {
        "type": "integer"
       }
      }
     },
     "key": {
      "type": "string",
      "description": "setExclusion: placedWithinDays or pipelineForJob. setFilter: the facet field."
     },
     "value": {
      "description": "setExclusion value: integer days, boolean, or null to clear."
     },
     "values": {
      "type": "array",
      "items": {
       "type": "string"
      },
      "description": "setFilter values. Empty clears the filter."
     }
    },
    "required": [
     "op"
    ]
   }
  },
  "reply": {
   "type": "string",
   "description": "Short reply shown in the chat, max 2 sentences."
  },
  "needsClarification": {
   "type": "boolean"
  }
 },
 "required": [
  "patch",
  "reply",
  "needsClarification"
 ]
}
